package io.github.deepseekbridge;

import android.content.Context;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.math.BigInteger;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import java.util.concurrent.*;

/** Official public-client OAuth. Tokens stay in native, Keystore-backed storage. */
final class OpenAiAccounts implements AutoCloseable {
    static final String ISSUER="https://auth.openai.com",AUTHORIZE=ISSUER+"/api/accounts/authorize",TOKEN=ISSUER+"/api/accounts/oauth/token",RESOURCE="https://api.openai.com/v1";
    interface Network {JSONObject json(String url,String method,String body)throws Exception;}
    interface Events {void emit(JSONObject value);}
    private final LocalState vault;private final Network network;private final Events events;
    private final ExecutorService io=Executors.newSingleThreadExecutor(r->new Thread(r,"studio-chatgpt-auth"));
    private volatile JSONObject data;private volatile Attempt pending;private volatile String notice="";private volatile boolean closed;
    static final class Attempt {String id,state,nonce,verifier,redirect,clientId,accountId,url;ServerSocket listener;long created=System.currentTimeMillis();}
    OpenAiAccounts(Context c,Events e){this(new LocalState(c,"studio-openai-accounts-v1","studio-openai-accounts-v1"),OpenAiAccounts::jsonHttp,e);}
    OpenAiAccounts(LocalState v,Network n,Events e){vault=v;network=n;events=e;try{data=new JSONObject(v.load());}catch(Exception ignored){data=new JSONObject();}}
    static String b64(byte[] bytes){return Base64.encodeToString(bytes,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
    static byte[] decode(String value){return Base64.decode(value,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
    static String random(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return b64(bytes);}
    private JSONArray accounts(){JSONArray a=data.optJSONArray("accounts");return a==null?new JSONArray():a;}
    private void save(JSONObject next)throws IOException {if(!vault.save(next.toString()))throw new IOException("账号凭据无法加密保存，未启用该账号");data=next;}
    private JSONObject account(String id)throws Exception {for(int i=0;i<accounts().length();i++){JSONObject a=accounts().getJSONObject(i);if(id.equals(a.optString("id")))return a;}throw new IOException("账号不存在，请重新登录");}
    JSONObject snapshot()throws Exception {JSONArray registered=data.optJSONArray("accounts");if(registered==null)registered=new JSONArray();JSONArray list=new JSONArray();for(int i=0;i<registered.length();i++){JSONObject a=registered.getJSONObject(i);list.put(new JSONObject().put("id",a.getString("id")).put("label",a.optString("label",a.optString("email","ChatGPT"))).put("email",a.optString("email")).put("signedIn",!a.optString("refresh_token").isEmpty()||!a.optString("access_token").isEmpty()).put("canInfer",hasScope(a,"chatgpt.tokens.use.direct")&&hasScope(a,"resource.invoke")).put("expiresAt",a.optLong("expiresAt")));}return new JSONObject().put("accounts",list).put("authorizing",pending!=null).put("notice",notice);}
    private void publish(){try{events.emit(new JSONObject().put("type","account").put("value",snapshot()));}catch(Exception ignored){}}
    static boolean hasScope(JSONObject a,String scope){return Arrays.asList(a.optString("scope").split("\\s+")).contains(scope);}
    synchronized JSONObject begin(String accountId)throws Exception {
        cancel();if(closed)throw new IOException("账号服务已关闭");if(accounts().length()>=8&&(accountId==null||accountId.isEmpty()))throw new IOException("最多保存 8 个账号注册");
        String host=data.optString("host");if(host.isEmpty()){host="urn:uuid:"+UUID.randomUUID();save(new JSONObject(data.toString()).put("host",host));}
        JSONObject old=accountId==null||accountId.isEmpty()?null:account(accountId);Attempt a=new Attempt();a.id=UUID.randomUUID().toString();a.state=random();a.nonce=random();a.verifier=random();a.clientId=old==null?"dynamic_agent_client":old.getString("client_id");a.accountId=old==null?null:old.getString("id");a.listener=new ServerSocket();a.listener.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0));a.listener.setSoTimeout(1000);a.redirect="http://127.0.0.1:"+a.listener.getLocalPort()+"/auth/callback";
        LinkedHashMap<String,String> q=new LinkedHashMap<>();q.put("client_id",a.clientId);if(old==null)q.put("agent_name_hint","Inkvoy");else {if(!old.optString("id_token").isEmpty())q.put("id_token_hint",old.getString("id_token"));if(!old.optString("email").isEmpty())q.put("login_hint",old.getString("email"));}q.put("ext_agent_host_id",host);q.put("response_type","code");q.put("redirect_uri",a.redirect);q.put("scope","openid profile email offline_access resource.invoke chatgpt.tokens.use.direct");q.put("resource",RESOURCE);q.put("state",a.state);q.put("nonce",a.nonce);q.put("code_challenge_method","S256");q.put("code_challenge",b64(MessageDigest.getInstance("SHA-256").digest(a.verifier.getBytes(StandardCharsets.US_ASCII))));a.url=AUTHORIZE+"?"+form(q);pending=a;notice="等待系统浏览器完成登录与授权";io.execute(()->listen(a));publish();return new JSONObject().put("pending",true);
    }
    String pendingUrl(){Attempt a=pending;return a==null?null:a.url;}
    void cancel(){Attempt a=pending;pending=null;if(a!=null)try{a.listener.close();}catch(IOException ignored){}notice="";}
    private void listen(Attempt a){try{while(pending==a&&!closed&&System.currentTimeMillis()-a.created<300000){try(Socket socket=a.listener.accept()){socket.setSoTimeout(3000);BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String line=reader.readLine();if(line==null||line.length()>16384)continue;String[] parts=line.split(" ");URI uri=parts.length>=2?new URI(parts[1]):null;Map<String,String> params=uri==null?Collections.emptyMap():query(uri.getRawQuery());boolean route=parts.length>=2&&parts[0].equals("GET")&&uri.getPath().equals("/auth/callback");if(!route||!same(a.state,params.get("state"))){respond(socket,400,"Invalid callback");continue;}try{complete(a,params);respond(socket,200,"Sign-in complete. You can return to Inkvoy.");}catch(Exception e){notice="登录未完成："+safeError(e);respond(socket,400,"Sign-in could not be completed. Return to Inkvoy.");}finally{if(pending==a)pending=null;a.listener.close();publish();}return;}catch(SocketTimeoutException ignored){}}if(pending==a){pending=null;notice="登录等待已超时，请重新发起授权";publish();}}catch(Exception e){if(pending==a){pending=null;notice="登录回调已中断，请重试";publish();}}finally{try{a.listener.close();}catch(Exception ignored){}}}
    private static void respond(Socket socket,int status,String message)throws IOException {byte[] body=("<!doctype html><meta charset=utf-8><meta name=viewport content=width=device-width><title>Inkvoy</title><p>"+message+"</p>").getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 "+status+(status==200?" OK":" Bad Request")+"\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: no-store\r\nContent-Security-Policy: default-src 'none'\r\nConnection: close\r\nContent-Length: "+body.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();}
    synchronized void complete(Attempt a,Map<String,String> params)throws Exception {
        if(pending!=a||!same(a.state,params.get("state")))throw new IOException("授权状态不匹配");if(params.containsKey("error"))throw new IOException("授权未获批准，请在账号页重新登录");String issued=params.get("client_id");if(a.clientId.equals("dynamic_agent_client")){if(issued==null||issued.isEmpty()||issued.equals("dynamic_agent_client"))throw new IOException("注册回调缺少正式 client_id");}else{if(issued!=null&&!issued.equals(a.clientId))throw new IOException("注册身份不匹配");issued=a.clientId;}String code=params.get("code");if(code==null||code.isEmpty())throw new IOException("授权码缺失");
        JSONObject tokens=network.json(TOKEN,"POST",form(new LinkedHashMap<String,String>(){{put("grant_type","authorization_code");put("client_id",params.getOrDefault("client_id",a.clientId));put("code",code);put("code_verifier",a.verifier);put("redirect_uri",a.redirect);put("resource",RESOURCE);}}));
        JSONObject discovery=discovery(),claims=verifyIdToken(tokens.getString("id_token"),network.json(discovery.getString("jwks_uri"),"GET",null),issued,a.nonce,System.currentTimeMillis()/1000);
        JSONObject old=a.accountId==null?null:account(a.accountId);if(old!=null&&(!old.getString("subject").equals(claims.getString("sub"))||!old.getString("issuer").equals(claims.getString("iss"))))throw new IOException("登录账号与所选注册不一致，原账号未更改");
        JSONObject next=old==null?new JSONObject().put("id",UUID.randomUUID().toString()):new JSONObject(old.toString());next.put("client_id",issued).put("subject",claims.getString("sub")).put("issuer",claims.getString("iss")).put("email",claims.optString("email")).put("label",claims.optString("email","ChatGPT")+" · "+issued.substring(Math.max(0,issued.length()-6)));applyTokens(next,tokens,false);next.put("id_token",tokens.getString("id_token"));replace(next);notice=hasScope(next,"chatgpt.tokens.use.direct")?"身份授权已完成；请读取模型以验证网络连接":"登录成功，但尚未授予 ChatGPT 计划调用权限";
    }
    private JSONObject discovery()throws Exception {JSONObject d=network.json(ISSUER+"/.well-known/openid-configuration","GET",null);if(!ISSUER.equals(d.optString("issuer")))throw new IOException("OpenAI 身份发现文档无效");for(String key:new String[]{"jwks_uri","revocation_endpoint"})if(d.has(key)){URI u=new URI(d.getString(key));if(!"https".equals(u.getScheme())||!"auth.openai.com".equals(u.getHost())||u.getUserInfo()!=null||u.getPort()!=-1)throw new IOException("OpenAI 身份端点无效");}return d;}
    private void replace(JSONObject account)throws Exception {JSONArray list=new JSONArray();boolean found=false;for(int i=0;i<accounts().length();i++){JSONObject old=accounts().getJSONObject(i);if(old.getString("id").equals(account.getString("id"))){list.put(account);found=true;}else list.put(old);}if(!found)list.put(account);save(new JSONObject(data.toString()).put("accounts",list));}
    static void applyTokens(JSONObject account,JSONObject tokens,boolean refresh)throws Exception {String access=tokens.getString("access_token");if(access.isEmpty()||!tokens.optString("token_type","Bearer").equalsIgnoreCase("Bearer"))throw new IOException("令牌响应无效");if(refresh&&tokens.optString("refresh_token").isEmpty())throw new IOException("刷新响应缺少轮换凭据，需重新登录");long expires=tokens.optLong("expires_in",3600);if(expires<1||expires>86400)throw new IOException("令牌有效期无效");account.put("access_token",access).put("expiresAt",System.currentTimeMillis()+expires*1000).put("scope",tokens.has("scope")?tokens.getString("scope"):account.optString("scope")).put("earliest_refresh_at",tokens.opt("earliest_refresh_at"));if(tokens.has("refresh_token"))account.put("refresh_token",tokens.getString("refresh_token"));}
    synchronized String access(String id)throws Exception {JSONObject a=new JSONObject(account(id).toString());if(!hasScope(a,"chatgpt.tokens.use.direct")||!hasScope(a,"resource.invoke"))throw new IOException("账号尚未授权模型调用，请重新登录并允许使用 ChatGPT 计划");if(a.optString("access_token").isEmpty())throw new IOException("账号已退出，请重新登录");if(a.optLong("expiresAt")<=System.currentTimeMillis()+60000){if(a.optString("refresh_token").isEmpty())throw new IOException("账号授权已过期，请重新登录");JSONObject tokens=network.json(TOKEN,"POST",form(new LinkedHashMap<String,String>(){{put("grant_type","refresh_token");put("client_id",a.getString("client_id"));put("refresh_token",a.getString("refresh_token"));put("resource",RESOURCE);}}));applyTokens(a,tokens,true);replace(a);}return a.getString("access_token");}
    synchronized JSONObject logout(String id)throws Exception {JSONObject a=new JSONObject(account(id).toString());boolean confirmed=false;try{if(!a.optString("refresh_token").isEmpty()){JSONObject d=discovery();String url=d.getString("revocation_endpoint");network.json(url,"POST",form(new LinkedHashMap<String,String>(){{put("token",a.getString("refresh_token"));put("token_type_hint","refresh_token");put("client_id",a.getString("client_id"));}}));confirmed=true;}else confirmed=true;}catch(Exception ignored){}for(String key:new String[]{"access_token","refresh_token","id_token","scope"})a.remove(key);a.put("expiresAt",0);replace(a);notice=confirmed?"账号已退出并撤销当前授权会话":"本机已退出；远端撤销未确认，可到 ChatGPT 设置中断开此应用";publish();return snapshot();}
    JSONObject handle(String operation,JSONObject args)throws Exception {switch(operation){case "account.diagnose":return diagnose();case "account.list":return snapshot();case "account.begin":return begin(args.optString("id"));case "account.cancel":cancel();publish();return snapshot();case "account.logout":return logout(args.getString("id"));default:throw new IOException("未知账号操作");}}
    static JSONObject diagnose()throws Exception {
        return NetworkSettings.diagnose(null);
    }
    static boolean same(String a,String b){return a!=null&&b!=null&&MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
    static Map<String,String> query(String raw)throws Exception {Map<String,String> values=new LinkedHashMap<>();if(raw!=null)for(String pair:raw.split("&")){String[] parts=pair.split("=",2);String key=URLDecoder.decode(parts[0],"UTF-8"),value=URLDecoder.decode(parts.length==2?parts[1]:"","UTF-8");if(values.put(key,value)!=null)throw new IOException("回调参数重复");}return values;}
    static String form(Map<String,String> values)throws Exception {StringBuilder b=new StringBuilder();for(Map.Entry<String,String> e:values.entrySet()){if(b.length()>0)b.append('&');b.append(URLEncoder.encode(e.getKey(),"UTF-8")).append('=').append(URLEncoder.encode(e.getValue(),"UTF-8"));}return b.toString();}
    static JSONObject verifyIdToken(String jwt,JSONObject jwks,String audience,String nonce,long now)throws Exception {
        String[] segments=jwt.split("\\.");if(segments.length!=3)throw new IOException("ID Token 结构无效");JSONObject header=new JSONObject(new String(decode(segments[0]),StandardCharsets.UTF_8)),claims=new JSONObject(new String(decode(segments[1]),StandardCharsets.UTF_8));String algorithm=header.getString("alg");if(!Arrays.asList("RS256","ES256").contains(algorithm))throw new IOException("不支持的 ID Token 签名算法");JSONObject key=null;JSONArray keys=jwks.getJSONArray("keys");for(int i=0;i<keys.length();i++){JSONObject k=keys.getJSONObject(i);if(header.optString("kid").equals(k.optString("kid"))&&(!k.has("alg")||algorithm.equals(k.optString("alg")))&&(!k.has("use")||k.optString("use").equals("sig"))){key=k;break;}}if(key==null)throw new IOException("未找到 ID Token 签名公钥");PublicKey publicKey;if(algorithm.equals("RS256")&&key.optString("kty").equals("RSA"))publicKey=KeyFactory.getInstance("RSA").generatePublic(new RSAPublicKeySpec(new BigInteger(1,decode(key.getString("n"))),new BigInteger(1,decode(key.getString("e")))));else if(algorithm.equals("ES256")&&key.optString("kty").equals("EC")&&key.optString("crv").equals("P-256")){AlgorithmParameters parameters=AlgorithmParameters.getInstance("EC");parameters.init(new ECGenParameterSpec("secp256r1"));publicKey=KeyFactory.getInstance("EC").generatePublic(new ECPublicKeySpec(new ECPoint(new BigInteger(1,decode(key.getString("x"))),new BigInteger(1,decode(key.getString("y")))),parameters.getParameterSpec(ECParameterSpec.class)));}else throw new IOException("ID Token 公钥类型不匹配");Signature signature=Signature.getInstance(algorithm.equals("RS256")?"SHA256withRSA":"SHA256withECDSA");signature.initVerify(publicKey);signature.update((segments[0]+"."+segments[1]).getBytes(StandardCharsets.US_ASCII));byte[] signed=decode(segments[2]);if(algorithm.equals("ES256"))signed=ecDer(signed);if(!signature.verify(signed))throw new IOException("ID Token 签名不匹配");boolean aud=audience.equals(claims.optString("aud"));JSONArray audiences=claims.optJSONArray("aud");if(audiences!=null){aud=false;for(int i=0;i<audiences.length();i++)aud|=audience.equals(audiences.optString(i));if(audiences.length()>1&&!audience.equals(claims.optString("azp")))aud=false;}if(!ISSUER.equals(claims.optString("iss"))||!aud||claims.optLong("exp",0)<now-30||claims.optLong("nbf",0)>now+30||claims.optLong("iat",0)>now+30||!same(nonce,claims.optString("nonce"))||claims.optString("sub").isEmpty())throw new IOException("ID Token 身份、受众、有效期或 nonce 无效");return claims;
    }
    static byte[] ecDer(byte[] raw)throws IOException {if(raw.length!=64)throw new IOException("无效 ECDSA 签名");byte[] r=new BigInteger(1,Arrays.copyOfRange(raw,0,32)).toByteArray(),s=new BigInteger(1,Arrays.copyOfRange(raw,32,64)).toByteArray();ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(48);out.write(4+r.length+s.length);out.write(2);out.write(r.length);out.write(r,0,r.length);out.write(2);out.write(s.length);out.write(s,0,s.length);return out.toByteArray();}
    static String safeError(Exception e){return e instanceof IOException&&e.getMessage()!=null&&!e.getMessage().contains("http")?e.getMessage().substring(0,Math.min(180,e.getMessage().length())):"授权交换或身份校验失败，请重新登录";}
    static JSONObject jsonHttp(String raw,String method,String body)throws Exception {URI u=new URI(raw);if(!"https".equals(u.getScheme())||!"auth.openai.com".equals(u.getHost())||u.getUserInfo()!=null||u.getPort()!=-1)throw new IOException("身份端点无效");HttpURLConnection c=NetworkSettings.open(u.toURL());try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(body!=null){byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}if(c.getResponseCode()!=200)throw new IOException("OpenAI 授权请求未成功（HTTP "+c.getResponseCode()+"），请重新登录");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>1048576)throw new IOException("身份响应超过容量");out.write(b,0,n);}return out.size()==0?new JSONObject():new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
    @Override public void close(){closed=true;cancel();io.shutdownNow();}
}
